item.text:
{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Missing information does not establish whether repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "70% in one reported run",
          "reason": "One reported score does not show variation across runs."
        }
      ],
      "instrument_review": "MESA 14 concerns whether repeated testing occurred; this is unclear. MESA 16 concerns score variation, which the single reported run does not establish."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "ran the evaluation exactly once",
          "reason": "A single run establishes neither stability nor instability."
        }
      ],
      "instrument_review": "MESA 14 is explicitly unmet because testing was not repeated. For MESA 16, score stability remains unknown."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated testing under the same conditions is explicitly described."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's stability threshold of at most two percentage points."
        }
      ],
      "instrument_review": "MESA 14 is supported by repeated runs under unchanged conditions. MESA 16 supports stability for this comparison under the report's stated definition."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "The developers tested variation across repeated runs under the same conditions."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the stated stability threshold of two percentage points."
        }
      ],
      "instrument_review": "MESA 14 is supported because repeated testing occurred, regardless of the outcome. Under MESA 16, the reported variation conflicts with the defined stability condition."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions provide no evidence of repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added documentation supplies no findings about score stability."
        }
      ],
      "instrument_review": "MESA 22 concerns documentation for repeating or examining an evaluation. Installation guidance does not resolve the missing repeated-run evidence relevant to MESA 14 and 16."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "A performed better on the evaluated puzzles under the stated scoring and conditions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "These results provide insufficient evidence for general intelligence across domains."
        }
      ],
      "instrument_review": "MESA 2 identifies a narrow intended use consistent with the results. MESA 9 and 20 provide no basis for extending this grid-puzzle comparison to general intelligence."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "The reported results support A's better performance on the evaluated grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "A broad intended use does not supply evidence of ability across domains."
        }
      ],
      "instrument_review": "Under MESA 2, the broad intended use is described. However, MESA 9 and 20 lack evidence for that scope, and MESA 25 would not support a general-intelligence conclusion from these results."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial scores alone supply no demonstrated link to improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial, blinded correctness checks and reported uncertainty interval support better correctness with A in the studied setting."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Improved decision correctness does not establish a safety improvement when safety was not measured."
        }
      ],
      "instrument_review": "MESA 20 lacks real-work evidence initially but gains relevant evidence from the later trial. MESA 16 is supported by the reported uncertainty interval. Under MESA 25, conclusions should remain limited to decision correctness in the studied workshop and conditions."
    }
  ],
  "closing_note": "No instructions were unclear. Missing evidence was treated as Not established, distinct from explicit contradiction."
}
